export type SpotKind = "food" | "drink" | "coffee" | "sweet" | "sight" | "shop" | "photo" | "wellness";

export type SavedSpot = {
  name: string;
  lat: number;
  lon: number;
  kind: SpotKind;
  /** Google Maps place id (cid), so the link opens the exact place. */
  cid: string;
  note?: string;
  /** False for places still on my want-to-go list. */
  tried: boolean;
};

export function spotHref(s: SavedSpot): string {
  return `https://maps.google.com/?cid=${s.cid}`;
}

